      "name": "FB_ViscosityDebounce",
      "kind": "FUNCTION_BLOCK",
      "declaration": "FUNCTION_BLOCK FB_ViscosityDebounce
VAR_INPUT
    IN : BOOL;
    PT : TIME;
    CycleTime : TIME;
END_VAR
VAR_OUTPUT
    Q : BOOL := FALSE;
END_VAR
VAR
    started : BOOL := FALSE;
    elapsed : LTIME := LTIME#0ns;
END_VAR",
      "implementation": "IF NOT IN THEN
    started := FALSE;
    elapsed := LTIME#0ns;
ELSIF NOT started THEN
    started := TRUE;
    elapsed := LTIME#0ns;
ELSIF elapsed < TIME_TO_LTIME(PT) THEN
    elapsed := elapsed + TIME_TO_LTIME(CycleTime);
    IF elapsed > TIME_TO_LTIME(PT) THEN
        elapsed := TIME_TO_LTIME(PT);
    END_IF;
END_IF;

Q := IN AND (elapsed >= TIME_TO_LTIME(PT));"
    }
  ]
}

